--###############
--## MONITORS ###
--###############

-- See https://wiki.hypr.land/Configuring/Monitors/
--
-- Machine-specific settings live in hosts/<hostname>.lua: monitor layout,
-- extra environment variables and startup commands (see hosts/nebula.lua).
-- Any screen not listed there — or every screen, on a machine without a
-- file — is set up automatically by the catch-all rule below, so plugging
-- in or removing a monitor needs no config change.

local HOME = os.getenv("HOME")
-- The kernel's hostname (the `hostname` program isn't in a base install).
local HOSTNAME = ""
do
    local f = io.open("/proc/sys/kernel/hostname")
    if f then HOSTNAME = (f:read("l") or ""):gsub("%s+", ""); f:close() end
end

local HOST = {}
do
    local file = HOME .. "/.config/hypr/hosts/" .. HOSTNAME .. ".lua"
    local ok, result = pcall(dofile, file)
    if ok and type(result) == "table" then
        HOST = result
    elseif not tostring(result):find("No such file") then
        -- The file exists but has an error: say so instead of failing silently.
        hl.notification.create({ text = "hosts/" .. HOSTNAME .. ".lua: " .. tostring(result), timeout = 10000 })
    end
end
local KNOWN_MONITORS = HOST.monitors or {}

for _, spec in ipairs(KNOWN_MONITORS) do
    hl.monitor(spec)
end

-- Everything else: best resolution, highest refresh rate, placed automatically.
hl.monitor({
    output   = "",
    mode     = "highrr",
    position = "auto",
    scale    = "auto",
})


