--## AUTOSTART ###
--################

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
-- exec-once = $terminal

-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("nm-applet &")
    hl.exec_cmd("awww-daemon &")
    hl.exec_cmd("dunst &")
    hl.exec_cmd("/usr/lib/hyprpolkitagent/hyprpolkitagent &")
    hl.exec_cmd("~/.config/profiles/switch.sh --apply &")
    hl.exec_cmd("~/.config/profiles/hotplug-daemon.sh &")
    -- First login on a new machine: write its screens into hosts/<hostname>.lua
    -- (does nothing once the file has a layout).
    hl.exec_cmd("~/.config/dotfiles-cli/commands/monitors save --if-empty")
    hl.exec_cmd("eww daemon")
    hl.exec_cmd("eww open bar")
    hl.exec_cmd("cursor-clip --daemon")
    hl.exec_cmd("hyprctl setcursor Windows-10 22")
    -- Same theme as gtk-3.0/gtk-4.0 settings.ini, for apps that read gsettings.
    hl.exec_cmd("gsettings set org.gnome.desktop.interface gtk-theme \"Adwaita-dark\"")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface color-scheme \"prefer-dark\"")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface icon-theme \"Papirus-Dark\"")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface cursor-theme \"Windows-10\"")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface cursor-size 22")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface font-name \"Inter 11\"")

    -- This machine's own startup commands (hosts/<hostname>.lua).
    for _, cmd in ipairs(HOST.startup or {}) do
        hl.exec_cmd(cmd)
    end
end)

