-- Per-monitor workspaces ------------------------------------------------
-- SUPER + 1..0          go to workspace 1..10 of the monitor you're on
-- SUPER + SHIFT + 1..0  move the active window there
--
-- Each monitor owns a block of 10 workspace IDs: the monitors listed in
-- hosts/<hostname>.lua get blocks in that order (1-10, 11-20, ...), any
-- other screen gets the next free block, ordered by position. The bar shows
-- 1..10 for each monitor, so the IDs themselves don't matter day to day.

local WS_PER_MONITOR = 10

-- Block number (1, 2, ...) for every connected monitor, by name.
local function monitor_blocks()
    local blocks, used = {}, 0
    for i, spec in ipairs(KNOWN_MONITORS) do
        blocks[spec.output] = i
        used = i
    end
    local others = {}
    for _, m in ipairs(hl.get_monitors()) do
        if not blocks[m.name] then others[#others + 1] = m end
    end
    -- Unknown screens: lower rows first (the desk), then left to right.
    table.sort(others, function(a, b)
        if a.y ~= b.y then return a.y > b.y end
        return a.x < b.x
    end)
    for _, m in ipairs(others) do
        used = used + 1
        blocks[m.name] = used
    end
    return blocks
end

-- Workspace ID for "number n on the monitor I'm on".
local function workspace_here(n)
    local monitor = hl.get_active_monitor()
    local block = (monitor and monitor_blocks()[monitor.name]) or 1
    return (block - 1) * WS_PER_MONITOR + n
end

-- Same, but if that workspace ended up on another screen (a monitor was
-- unplugged, or it's left over from an older numbering), bring it back here
-- first, so SUPER+1 never jumps to a different monitor.
local function own_workspace_here(n)
    local id = workspace_here(n)
    local monitor = hl.get_active_monitor()
    local ws = hl.get_workspace(id)
    if monitor and ws and ws.monitor and ws.monitor.name ~= monitor.name then
        hl.dispatch(hl.dsp.workspace.move({ workspace = id, monitor = monitor.name }))
    end
    return id
end

for n = 1, WS_PER_MONITOR do
    local key = tostring(n % 10)          -- 1..9, then 0 for the 10th
    hl.bind(mainMod .. " + " .. key, function()
        hl.dispatch(hl.dsp.focus({ workspace = own_workspace_here(n) }))
    end)
    hl.bind(mainMod .. " + SHIFT + " .. key, function()
        hl.dispatch(hl.dsp.window.move({ workspace = own_workspace_here(n) }))
    end)
end

-- Pin each known monitor's block to it, so its workspaces stay on that
-- screen (and go back to it when it's turned off and on again, like the TV).
for i, spec in ipairs(KNOWN_MONITORS) do
    for n = 1, WS_PER_MONITOR do
        hl.workspace_rule({
            workspace = tostring((i - 1) * WS_PER_MONITOR + n),
            monitor   = spec.output,
            default   = (n == 1),
        })
    end
end

